import { CPU } from "./cpu.js";
import { INSTRUCTIONS } from "./cpuInstructionReverse.js";

let cpu = new CPU({debugMode: true});  // Initialize CPU instance
let p, c, z, i, d, b, v, n;
let a, x, y, pc, sp, masterCycles;

function getFlagStatus() {
    const temp = cpu.getFlags();
    c = temp[0];
    z = temp[1];
    i = temp[2];
    d = temp[3];
    b = temp[4];
    v = temp[5];
    n = temp[6];
    p = temp[7];

    document.getElementById("flags").innerHTML = "Flag Register: " + hex(p) + "<br>NV-BDIZC<br>" + n + v + "0" + b + d + i + z + c + "<br>";
}

function getRegisters() {
    const temp = cpu.getRegisters();
    a = temp[0];
    x = temp[1];
    y = temp[2];
    pc = temp[3];
    sp = temp[4];
    masterCycles = temp[5];
    document.getElementById("regA").innerText = hex(a);
    document.getElementById("regX").innerText = hex(x);
    document.getElementById("regY").innerText = hex(y);
    document.getElementById("regPC").innerText = hex(pc, 4);
    document.getElementById("regSP").innerText = hex(sp);
    document.getElementById("cycles").innerText = masterCycles;
}

function updateHtml () {
    getFlagStatus();
    getRegisters();
    debugMemoryDump(0x0000, "zeroPageDump");
    debugMemoryDump(0x0100, "stackPageDump");
    debugMemoryDump("PC", "memDump");
}

function writeToMemory(startAddress, values) {
    for (let i = 0; i < values.length; i++) {
        cpu.memory[(startAddress + i) & 0xFFFF] = values[i] & 0xFF; // Ensure only the least significant byte is written to memory
    }
}

function readFromMemory(address, length) {
    let result = [];
    for (let i = 0; i < length; i++) {
        result.push(cpu.memory[(address + i) & 0xFFFF] & 0xFF); // Ensure only the least significant byte is read from memory
    }
    return result;
}

function logMemory(startAddress, length = 16) {
    if (startAddress % 16 !== 0) {
        startAddress = startAddress - (startAddress % 16);
    }
    if (length != 16) {
        length = 16;
    }
    let output = "0x" + hex(startAddress, 4, false) + " : ";
    
    let outputChars = "";
    for (let i = 0; i < length; i++) {
        if ((startAddress + i) === cpu.getRegister("PC")) {
            output += `<span id="ProgramCounter">` + hex(cpu.memory[(startAddress + i) & 0xFFFF], 2, false) + `</span> `;
        } else if ((startAddress + i) === (0x0100 | cpu.getRegister("SP"))) {
            output += `<span id="StackPointer">` + hex(cpu.memory[(startAddress + i) & 0xFFFF], 2, false) + `</span> `;
        } else {
            output += hex(cpu.memory[(startAddress + i) & 0xFFFF], 2, false) + " ";
        }
        if ((startAddress + i) === cpu.getRegister("PC")) {
            outputChars += `<span id="ProgramCounter">` + printableCharacter(cpu.memory[(startAddress + i) & 0xFFFF]) + `</span>`;
        } else if ((startAddress + i) === (0x0100 | cpu.getRegister("SP"))) {
            outputChars += `<span id="StackPointer">` + printableCharacter(cpu.memory[(startAddress + i) & 0xFFFF]) + `</span>`;
        } else {
            outputChars += printableCharacter(cpu.memory[(startAddress + i) & 0xFFFF]);
        }
        
        if (i === 7) {
            output += "   ";  // Extra space in the middle for readability
            outputChars += " ";  // Extra space in the middle for readability
        }
    }
    output += "    |" + outputChars + "|";
    if (cpu.getRegister("PC") >= startAddress && cpu.getRegister("PC") < startAddress + length) {
        return '<span class="current-line">' + output + '</span>';
    } else {
        return output;
    }
    
}

function hex(value, digits = 2, preamble = true) {
    const hexValue = value.toString(16).toUpperCase().padStart(digits, '0');
    return preamble ? "0x" + hexValue : hexValue;
}

function printableCharacter(value) {
    const char = String.fromCharCode(value);
    return char.match(/[\x20-\x7E]/) ? char : '.';
}

function debugMemoryDump (value, location) {
    let output = "Address: 00 01 02 03 04 05 06 07    08 09 0A 0B 0C 0D 0E 0F\n";
    output += "-----------------------------------------------------------\n";
    if (value === "PC") {
        output += logMemory((cpu.getRegister("PC") - 32) & 0xFFFF, 16) + "\n";
        output += logMemory((cpu.getRegister("PC") - 16) & 0xFFFF, 16) + "\n";
        output += logMemory(cpu.getRegister("PC") & 0xFFF0, 16) + "\n";
        output += logMemory((cpu.getRegister("PC") + 16) & 0xFFFF, 16) + "\n";
        output += logMemory((cpu.getRegister("PC") + 32) & 0xFFFF, 16) + "\n";
        output += "<p></p>";
        output += "Next instruction: " + INSTRUCTIONS[cpu.memory[cpu.getRegister("PC")]] + " (Opcode: " + hex(cpu.memory[cpu.getRegister("PC")]) + ")";
    } else {
        output += logMemory(value, 16) + "\n";
        output += logMemory((value + 0x10) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0x20) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0x30) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0x40) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0x50) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0x60) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0x70) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0x80) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0x90) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0xA0) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0xB0) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0xC0) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0xD0) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0xE0) & 0xFFF0, 16) + "\n";
        output += logMemory((value + 0xF0) & 0xFFF0, 16) + "\n";
    }
    document.getElementById(location).innerHTML = output;
}

function onMousePressed() {
    cpu.step();
    updateHtml();
}

